input.command:
python3 - <<'EOF'
import json, os
def load(m, tag, c):
    f = f"results/dk_grid/{m}/{tag}_c{c}.json"
    return json.load(open(f)) if os.path.exists(f) else None
def tau(N, a):  # N tokens verified = N-1 drafts + bonus, constant per-position acceptance a
    return sum(a ** d for d in range(N))
print("Per-position acceptance alpha* above which a 16-token verify (k=15) beats 4- and 8-token ones,")
print("from measured step costs (DFlash k=3/7/15; cost includes the drafter). Current alpha: DFlash ~0.65-0.78, MTP ~0.78-0.82.\n")
for m in ("gemma-4-31B-it", "gemma-4-26B-A4B-it"):
    print(m)
    for c in (4, 16, 64, 128):
        cost = {}
        for k in (3, 7, 15):
            r, a = load(m, f"dflash{k}", c), load(m, "ar", c)
            cost[k + 1] = r["spec_decode_acceptance_length"] / (r["output_throughput"] / a["output_throughput"])
        best = None
        for i in range(500, 1000):
            al = i / 1000
            sp = {N: tau(N, al) / cost[N] for N in cost}
            if max(sp, key=sp.get) == 16:
                best = al; break
        sp_now = {N: tau(N, 0.75) / cost[N] for N in cost}
        sp_09 = {N: tau(N, 0.90) / cost[N] for N in cost}
        print(f"  c={c:3d}  cost(N=4,8,16) = {cost[4]:.2f} {cost[8]:.2f} {cost[16]:.2f}   alpha* = {best}   "
              f"speedup at alpha 0.75: best N={max(sp_now, key=sp_now.get)} {max(sp_now.values()):.2f}x   "
              f"at alpha 0.90: N=16 {sp_09[16]:.2f}x (best N={max(sp_09, key=sp_09.get)})")
EOF

