            res[f"sib{g}"] = tau(sub, f"sib{g}")
            res[f"coverage{g}"] = round(float(np.mean([r[f"sib{g}_m"] >= N_INDEX for r in sub])), 3)
            res[f"oracle{g}"] = round(1 + float(np.mean([max(r["drafter"], r[f"sib{g}"]) for r in sub])), 3)
            for m0 in (4, 8):
