                    [r[f"sib{g}"] if r[f"sib{g}_m"] >= m0 else r["drafter"] for r in sub])), 3)
        return res

    result = {"seeds": seeds, "K": K, "all": report(rows)}
    for c in CATS:
        sub = [r for r in rows if r["cat"] == c]
        if sub:
            result[c] = report(sub)
    json.dump(result, open(f"{root}/{tag}_siblings.json", "w"), indent=1)

    cols = ["all"] + [c for c in CATS if c in result]
    keys = ["steps", "drafter", "self", "other_prompts"] + [f"sib{g}" for g in groups] + ["sib_completed"] + \
        [f"coverage{g}" for g in groups] + [f"oracle{g}" for g in groups] + \
        [f"switch{m0}_{g}" for m0 in (4, 8) for g in groups]
    print(f"seeds {seeds}; tau = 1 + accepted tokens per step (K={K}); sibN = N time-aligned siblings")
    print(f"{'':16}" + "".join(f"{c[:11]:>12}" for c in cols))
    for k in keys:
        print(f"{k:16}" + "".join(f"{str(result[c][k]):>12}" for c in cols))


